  ME: "4d6+6"
  MA: "4d6"
  PS: "3d6"
  PP: "3d6"
  PE: "2d6"
  PB: "2d6"
  Spd: "2d6"
hit_points_base: "P.E. + 1D6 per level"
ppe_base: "5d6"
horror_factor: 10
